/// Volume-source distribution model for the FEM right-hand side.
///
/// Both variants use the same `-iωρQ` monopole coefficient. `amplitude = 1`
/// maps to the calibrated [`super::consts::SOURCE_VOLUME_VELOCITY_REFERENCE`]
/// volume velocity; the variants differ only in how the Dirac source is
/// regularized on the mesh.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum FemSourceModel {
    /// Normalized Gaussian of the given sigma (m). A fixed sigma low-pass
    /// filters the free-field monopole response by ~exp(-(kσ)²/2) (for
    /// σ = 0.1 m that is −14.6 dB at 1 kHz and −58 dB at 2 kHz), so this
    /// variant is retained only for reference-solver cross-checks that
    /// reproduce the historical Gaussian problem.
    Gaussian {
        /// Gaussian standard deviation in meters.
        sigma: f64,
    },
    /// Compact discrete delta: the monopole load is distributed over the
    /// containing tetrahedron's nodes with its P1 shape-function weights at
    /// the source point. The weights sum to one on any mesh, so the
    /// integrated strength equals the prescribed volume velocity independent
    /// of mesh density and frequency — the broadband monopole is not
    /// low-pass filtered by an artificial source width.
    PointLoad,
}

/// How much per-frequency solution evidence a GPU sweep downloads.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum GpuSolutionEvidence {
    /// Download the full nodal solution per frequency and accumulate the
    /// host-side operator-work / boundary-power evidence (current
    /// behaviour). Costs one `n·n_sources·16` B D2H per frequency.
    #[default]
    Full,
    /// Skip the full-solution download: listener pressures are already
    /// evaluated on-device, so only they cross back to the host.
    /// Per-frequency power evidence is omitted (`None`) in diagnostics
    /// and downstream metadata. Listener pressures are bit-identical to
    /// [`Self::Full`] (SIM-PERF-20261013.md section 6, recommendation 3).
    ListenersOnly,
}

impl GpuSolutionEvidence {
    /// Canonical CLI spelling.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Full => "full",
            Self::ListenersOnly => "listeners",
        }
    }
}

impl std::fmt::Display for GpuSolutionEvidence {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

impl std::str::FromStr for GpuSolutionEvidence {
    type Err = String;

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        match value.to_ascii_lowercase().as_str() {
            "full" => Ok(Self::Full),
            "listeners" | "listeners-only" | "listeners_only" => Ok(Self::ListenersOnly),
            other => Err(format!(
                "unknown GPU solution evidence '{other}' (expected 'full' or 'listeners')"
            )),
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct FemMeshConfig {
    /// Target elements per shortest wavelength before applying far-field grading.
    ///
    /// Defaults to six. Increase for resolved complex-field accuracy or a
    /// refinement study; every mesh-export and solver path honors this value.
    pub elements_per_wavelength: f64,
    /// Far-field coarsening multiplier. 1.0 = uniform mesh (legacy behaviour).
    pub grading_factor: f64,
    /// Radius (m) around projected POIs within which the fine spacing is kept.
    pub fine_radius: f64,
    /// Shifted-Laplacian preconditioner used by GMRES.
    pub preconditioner: FemPreconditionerKind,
    /// Number of harmonic Ritz vectors recycled across adjacent frequencies.
    /// Set to 0 to use plain restarted GMRES with the previous solution as x0.
    pub recycle_subspace_size: usize,
    /// Algorithm used when `recycle_subspace_size > 0`. Defaults to `GcroDr`.
    pub recycler: RecyclerKind,
    /// Rebuild the shifted-Laplacian preconditioner only every N-th frequency
    /// of the sweep. 1 (default) rebuilds on every frequency — exact.
    /// N > 1 reuses the same factorisation for N adjacent frequencies, which
    /// trades a small drop in preconditioner quality (P(k_n) is no longer
    /// exact for `k_{n+1}, …, k_{n+N-1}`) for the dominant ILUT/AMG setup
    /// cost amortised across N solves. Per-iteration count typically grows
    /// sub-linearly with N — the wall-clock optimum is usually 5–10.
    pub rebuild_precond_every: usize,
    /// Clear the recycled subspace every M-th frequency of the sweep so it
    /// rebuilds from scratch. 0 (default) never resets and lets the recycler
    /// accumulate harmonic Ritz vectors across the whole sweep — the solver
    /// already clears the recycler automatically on a first-pass convergence
    /// failure, so a periodic forced reset usually does more harm than good.
    /// Set M>0 (e.g. 10) only if you have evidence the recycler is injecting
    /// stale Ritz directions in a sustained dense-modal band.
    pub recycle_reset_every: usize,
    /// GMRES relative-residual convergence tolerance. 1e-6 is the calibrated
    /// default and matches f64 assembly/quadrature error; loosening to 1e-5
    /// cuts iteration count ~15–20% and is invisible in the resulting impulse
    /// responses. Below 1e-7 the iteration is wasted — discretisation error
    /// dominates.
    pub gmres_tolerance: f64,
    /// GMRES restart window m. Caps the Arnoldi orthogonalisation cost at
    /// O(m·n) per cycle and the Hessenberg storage at O(m²). 50 is the
    /// calibrated default for block-Jacobi / ILUT. With AMG / FGMRES the
    /// preconditioner gives a much better Krylov space and m=30 is enough;
    /// with weak preconditioners go higher (60–80).
    pub gmres_restart: usize,
    /// Minimum imaginary-axis offset applied to the FEM wavenumber, expressed
    /// as a fraction of `k_real`. This is an explicit volumetric loss model on
    /// top of boundary admittance and atmospheric absorption. The default
    /// 0.0005 gives a 0.05% modal damping floor, retained only as a pole
    /// regularizer; set 0.0 to disable the floor and retain only atmospheric
    /// absorption.
    pub modal_damping_ratio: f64,
    /// Complex shift used to build the shifted-Laplacian preconditioner
    /// P = K + shift · M from the Helmholtz operator's K and M.
    pub shifted_laplacian_shift: ShiftedLaplacianShift,
    /// Volume-source distribution model. Defaults to [`FemSourceModel::PointLoad`],
    /// the mesh-independent discrete delta; the Gaussian variant is retained
    /// for reference-solver cross-checks.
    pub source_model: FemSourceModel,
    /// Solve all source right-hand sides of a frequency as ONE block system
    /// (block GMRES, or block FGMRES for flexible preconditioners) instead of
    /// independent per-source solves. Default false (per-source path).
    ///
    /// The block path walks the operator and preconditioner once per Arnoldi
    /// step for all k sources (sparse SpMM, BLAS-3 block orthogonalisation)
    /// and lets each source search Krylov directions generated from the other
    /// sources' residuals. Its value is greatest when threads are scarce —
    /// e.g. under frequency-lane or mode-lane parallelism where each lane
    /// owns few rayon workers — because the k-fold reduction in operator
    /// passes is pure win there. With all threads available, the parallel
    /// per-source path usually wins on wall-clock.
    ///
    /// The block solve uses the previous frequency's stacked solutions as a
    /// warm-start `X₀`; per-source subspace recycling (GCRO-DR) is NOT used
    /// on the block path (block GCRO-DR is future work). Correctness is
    /// preserved either way: every RHS is gated on its recomputed true
    /// residual afterwards, and any source failing the gate falls back to the
    /// existing per-source retry ladder (recycler, strong ILUT, BiCGSTAB).
    ///
    /// Currently honoured by the full-domain runner only; the symmetric
    /// mode-parallel runner always uses the per-source path.
    pub block_source_solve: bool,
    /// Permit an explicit room-side crossover after a complex directivity
    /// grid. Such grids normally already contain crossover magnitude and
    /// phase; leaving this false prevents accidental double-filtering. Set
    /// true only when the chained filter is deliberate.
    pub allow_chained_complex_crossover: bool,
    /// How much per-frequency solution evidence a GPU (CUDA/Metal) sweep
    /// downloads. [`GpuSolutionEvidence::ListenersOnly`] skips the full
    /// nodal-solution D2H (`n·n_sources·16` B per frequency) because
    /// listener pressures are already evaluated on-device; power
    /// evidence is then omitted from diagnostics. CPU sweeps ignore
    /// this field (their solutions are already host-side).
    pub gpu_solution_evidence: GpuSolutionEvidence,
}

impl Default for FemMeshConfig {
    fn default() -> Self {
        Self {
            elements_per_wavelength: ELEMENTS_PER_WAVELENGTH,
            grading_factor: 1.0,
            fine_radius: 0.5,
            preconditioner: FemPreconditionerKind::default(),
            recycle_subspace_size: DEFAULT_RECYCLE_SUBSPACE_SIZE,
            recycler: RecyclerKind::default(),
            rebuild_precond_every: 5,
            recycle_reset_every: 0,
            gmres_tolerance: 1e-6,
            gmres_restart: GMRES_RESTART,
            modal_damping_ratio: DEFAULT_MODAL_DAMPING_RATIO,
            shifted_laplacian_shift: ShiftedLaplacianShift::default(),
            source_model: FemSourceModel::PointLoad,
            block_source_solve: false,
            allow_chained_complex_crossover: false,
            gpu_solution_evidence: GpuSolutionEvidence::default(),
        }
    }
}

pub(super) fn effective_recycle_subspace_size(mesh_config: &FemMeshConfig) -> usize {
    mesh_config
        .recycle_subspace_size
        .min(GMRES_RESTART.saturating_sub(1))
}

fn insert_axis_breakpoint(coords: &mut Vec<f64>, value: f64) {
    if !coords
        .iter()
        .any(|coordinate| (*coordinate - value).abs() <= 1.0e-12)
    {
        coords.push(value);
        coords.sort_by(f64::total_cmp);
    }
}

fn cell_is_inside_room(room: &RoomGeometry, x: f64, y: f64) -> bool {
    match room {
        RoomGeometry::Rectangular(_) => true,
        RoomGeometry::LShaped(room) => {
            (y <= room.depth1 && x <= room.width1) || (y >= room.depth1 && x <= room.width2)
        }
    }
}

fn grid_node(
    mesh: &mut Mesh,
    node_ids: &mut [Option<usize>],
    xs: &[f64],
    ys: &[f64],
    zs: &[f64],
    index: (usize, usize, usize),
) -> usize {
    let (i, j, k) = index;
    let flat = k * ys.len() * xs.len() + j * xs.len() + i;
    *node_ids[flat].get_or_insert_with(|| mesh.add_node(Point::new_3d(xs[i], ys[j], zs[k])))
}

/// Create a tetrahedral mesh for the room using conforming 6-tetrahedron decomposition.
/// With symmetry, meshes only the reduced domain (half or quarter).
///
/// When `mesh_config.grading_factor > 1.0`, the per-axis 1D coord arrays are
/// non-uniform: fine spacing within `fine_radius` of any source/listening
/// position (folded into the reduced domain) and up to `grading_factor` times
/// coarser far away. The structured tensor-product topology is preserved, so
/// the conforming 6-tet decomposition still works for hex cells of any size.
pub(super) fn create_room_mesh(
    simulation: &RoomSimulation,
    elements_per_meter: usize,
    symmetry: &SymmetryConfig,
    mesh_config: &FemMeshConfig,
) -> Mesh {
    let (width, depth, height) = simulation.room.dimensions();

    // Reduced dimensions for symmetry
    let eff_width = if symmetry.has_x() { width / 2.0 } else { width };
    let eff_depth = if symmetry.has_y() { depth / 2.0 } else { depth };

    let h_fine = 1.0 / elements_per_meter as f64;
    let h_coarse = h_fine * mesh_config.grading_factor.max(1.0);

    // Collect POIs (sources + listening positions) folded into the reduced domain.
    let mut pois_x = Vec::new();
    let mut pois_y = Vec::new();
    let mut pois_z = Vec::new();
    let fold = |p: Point3D| -> (f64, f64, f64) {
        let (q, _) = map_to_reduced_domain(p, symmetry, width, depth);
        (q.x, q.y, q.z)
    };
    for src in &simulation.sources {
        let (x, y, z) = fold(src.position);
        pois_x.push(x);
        pois_y.push(y);
        pois_z.push(z);
    }
    for lp in &simulation.listening_positions {
        let (x, y, z) = fold(*lp);
        pois_x.push(x);
        pois_y.push(y);
        pois_z.push(z);
    }

    let mut xs = build_axis_coords(
        eff_width,
        h_fine,
        h_coarse,
        &pois_x,
        mesh_config.fine_radius,
    );
    let mut ys = build_axis_coords(
        eff_depth,
        h_fine,
        h_coarse,
        &pois_y,
        mesh_config.fine_radius,
    );
    let zs = build_axis_coords(height, h_fine, h_coarse, &pois_z, mesh_config.fine_radius);
    if let RoomGeometry::LShaped(room) = &simulation.room {
        assert!(
            !symmetry.has_x() && !symmetry.has_y(),
            "L-shaped rooms do not support rectangular symmetry reduction"
        );
        insert_axis_breakpoint(&mut xs, room.width2);
        insert_axis_breakpoint(&mut ys, room.depth1);
    }
    let nx = xs.len();
    let ny = ys.len();
    let nz = zs.len();

    // Reflection symmetry of the axis grids about the full-room centre
    // planes. When a full-span grid is mirror-symmetric, cells on the far
    // side of the centre use the mirrored body diagonal (see the element
    // loop), so the whole mesh is invariant under the same reflections the
    // symmetry-exploiting solver assumes. Reduced (half-domain) grids span
    // only the near side and keep the base diagonal throughout, matching
    // the full mesh's near half cell for cell. Non-symmetric grids keep
    // the uniform diagonal everywhere.
    let grid_symmetric = |coords: &[f64], length: f64| {
        coords.len() >= 2
            && coords
                .iter()
                .zip(coords.iter().rev())
                .all(|(a, b)| (a + b - length).abs() < 1e-9)
    };
    // The diagonal may only switch exactly on the centre plane: if a cell
    // straddled the centre, its two neighbours would induce different
    // diagonals on their shared face and the P1 mesh would be
    // non-conforming. Require a grid plane on the centre.
    let centre_on_grid = |coords: &[f64], length: f64| {
        coords.iter().any(|&c| (c - 0.5 * length).abs() < 1e-9)
    };
    // Mirroring is only meaningful when the physical problem (room,
    // boundaries, sources) is itself symmetric in that axis; otherwise the
    // diagonal flip would just change the mesh family arbitrarily.
    let detected = detect_symmetry(simulation);
    let x_mirrored = (eff_width - width).abs() < 1e-12
        && detected.has_x()
        && grid_symmetric(&xs, width)
        && centre_on_grid(&xs, width);
    let y_mirrored = (eff_depth - depth).abs() < 1e-12
        && detected.has_y()
        && grid_symmetric(&ys, depth)
        && centre_on_grid(&ys, depth);

    let mut mesh = Mesh::new(3);
    let mut node_ids = vec![None; nx * ny * nz];

    for k in 0..(nz - 1) {
        for j in 0..(ny - 1) {
            for i in 0..(nx - 1) {
                let center_x = 0.5 * (xs[i] + xs[i + 1]);
                let center_y = 0.5 * (ys[j] + ys[j + 1]);
                if !cell_is_inside_room(&simulation.room, center_x, center_y) {
                    continue;
                }
                let v0 = grid_node(&mut mesh, &mut node_ids, &xs, &ys, &zs, (i, j, k));
                let v1 = grid_node(&mut mesh, &mut node_ids, &xs, &ys, &zs, (i + 1, j, k));
                let v2 = grid_node(&mut mesh, &mut node_ids, &xs, &ys, &zs, (i, j + 1, k));
                let v3 = grid_node(&mut mesh, &mut node_ids, &xs, &ys, &zs, (i + 1, j + 1, k));
                let v4 = grid_node(&mut mesh, &mut node_ids, &xs, &ys, &zs, (i, j, k + 1));
                let v5 = grid_node(&mut mesh, &mut node_ids, &xs, &ys, &zs, (i + 1, j, k + 1));
                let v6 = grid_node(&mut mesh, &mut node_ids, &xs, &ys, &zs, (i, j + 1, k + 1));
                let v7 = grid_node(
                    &mut mesh,
                    &mut node_ids,
                    &xs,
                    &ys,
                    &zs,
                    (i + 1, j + 1, k + 1),
                );

                // Six tets on one body diagonal per cell. The diagonal is
                // mirrored across the room centre planes when the axis grid
                // is symmetric there (x_mirrored / y_mirrored), which keeps
                // shared face diagonals paired on both sides of each centre
                // plane while making the mesh reflection-invariant. Other
                // alternating patterns would mismatch shared face diagonals,
                // leaving unpaired interior triangles in the P1 mesh.
                let v = [v0, v1, v2, v3, v4, v5, v6, v7];
                let mirror_x = x_mirrored && center_x > 0.5 * width;
                let mirror_y = y_mirrored && center_y > 0.5 * depth;
                let perm: [usize; 8] = match (mirror_x, mirror_y) {
                    (false, false) => [0, 1, 2, 3, 4, 5, 6, 7],
                    (true, false) => [1, 0, 3, 2, 5, 4, 7, 6],
                    (false, true) => [2, 3, 0, 1, 6, 7, 4, 5],
                    (true, true) => [3, 2, 1, 0, 7, 6, 5, 4],
                };
                const BASE_TETS: [[usize; 4]; 6] = [
                    [0, 1, 3, 7],
                    [0, 1, 7, 5],
                    [0, 5, 7, 4],
                    [0, 3, 2, 7],
                    [0, 2, 6, 7],
                    [0, 6, 4, 7],
                ];
                for base in BASE_TETS {
                    let mut tet = base.map(|corner| v[perm[corner]]);
                    if mirror_x != mirror_y {
                        // A single reflection flips tet orientation; restore
                        // positive volume by swapping two corners.
                        tet.swap(0, 1);
                    }
                    mesh.add_element(ElementType::Tetrahedron, tet.to_vec());
                }
            }
        }
    }

    mesh.detect_boundaries();

    let eps = 1e-6;

    mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_FLOOR, |pts| {
        pts.iter().all(|p| p.z.abs() < eps)
    });
    mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_CEILING, |pts| {
        pts.iter().all(|p| (p.z - height).abs() < eps)
    });
    mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_FRONT, |pts| {
        pts.iter().all(|p| p.y.abs() < eps)
    });
    mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_LEFT, |pts| {
        pts.iter().all(|p| p.x.abs() < eps)
    });

    // The "max-x" and "max-y" faces are either physical walls or symmetry cut planes
    if symmetry.has_x() {
        mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_SYM_X, |pts| {
            pts.iter().all(|p| (p.x - eff_width).abs() < eps)
        });
    } else if let RoomGeometry::LShaped(room) = &simulation.room {
        mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_RIGHT, |pts| {
            pts.iter().all(|p| {
                ((p.x - room.width1).abs() < eps && p.y <= room.depth1 + eps)
                    || ((p.x - room.width2).abs() < eps && p.y >= room.depth1 - eps)
            })
        });
    } else {
        mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_RIGHT, |pts| {
            pts.iter().all(|p| (p.x - eff_width).abs() < eps)
        });
    }

    if symmetry.has_y() {
        mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_SYM_Y, |pts| {
            pts.iter().all(|p| (p.y - eff_depth).abs() < eps)
        });
    } else if let RoomGeometry::LShaped(room) = &simulation.room {
        let total_depth = room.depth1 + room.depth2;
        mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_BACK, |pts| {
            pts.iter().all(|p| {
                (p.y - total_depth).abs() < eps
                    || ((p.y - room.depth1).abs() < eps && p.x >= room.width2 - eps)
            })
        });
    } else {
        mesh.set_boundary_condition(BoundaryType::Neumann, MARKER_BACK, |pts| {
            pts.iter().all(|p| (p.y - eff_depth).abs() < eps)
        });
    }

    mesh
}

/// Reuse the most recently generated mesh when consecutive scenarios have
/// identical geometry, refinement points, symmetry, and mesh controls.
///
/// The cache is deliberately one-entry: room meshes can be large, and dataset
/// scenarios are grouped by room. Holding the last mesh captures that reuse
/// without accumulating the entire scenario matrix in memory.
pub(super) fn cached_room_mesh(
    simulation: &RoomSimulation,
    elements_per_meter: usize,
    symmetry: &SymmetryConfig,
    mesh_config: &FemMeshConfig,
) -> Arc<Mesh> {
    type CachedRoomMesh = Mutex<Option<(String, Arc<Mesh>)>>;
    static LAST_MESH: OnceLock<CachedRoomMesh> = OnceLock::new();
    let source_positions = simulation
        .sources
        .iter()
        .map(|source| source.position)
        .collect::<Vec<_>>();
    let key = format!(
        "{:?}|{elements_per_meter}|{:?}|{:?}|{:?}|{:?}",
        simulation.room, symmetry, mesh_config, source_positions, simulation.listening_positions,
    );
    let cache = LAST_MESH.get_or_init(|| Mutex::new(None));
    if let Some((cached_key, mesh)) = cache.lock().expect("room mesh cache poisoned").as_ref()
        && cached_key == &key
    {
        log::info!("FEM: reusing mesh from previous scenario");
        return Arc::clone(mesh);
    }

    let mesh = Arc::new(create_room_mesh(
        simulation,
        elements_per_meter,
        symmetry,
        mesh_config,
    ));
    *cache.lock().expect("room mesh cache poisoned") = Some((key, Arc::clone(&mesh)));
    mesh
}

#[cfg(test)]
mod l_shaped_tests {
    use super::*;
    use sonium_xem::{LShapedRoom, RectangularRoom};

    #[test]
    fn identical_consecutive_scenarios_share_the_cached_mesh() {
        let simulation = RoomSimulation::new(
            RoomGeometry::Rectangular(RectangularRoom::new(2.0, 1.5, 1.2)),
            Vec::new(),
            Vec::new(),
        );
        let config = FemMeshConfig::default();
        let first = cached_room_mesh(&simulation, 2, &SymmetryConfig::none(), &config);
        let second = cached_room_mesh(&simulation, 2, &SymmetryConfig::none(), &config);
        assert!(Arc::ptr_eq(&first, &second));
    }

    #[test]
    fn l_shaped_mesh_omits_the_bounding_box_cutout() {
        let room = LShapedRoom::new(4.0, 3.0, 2.0, 2.0, 2.5);
        let simulation =
            RoomSimulation::new(RoomGeometry::LShaped(room.clone()), Vec::new(), Vec::new());
        let mesh = create_room_mesh(
            &simulation,
            2,
            &SymmetryConfig::none(),
            &FemMeshConfig::default(),
        );

        assert!(
            mesh.nodes.iter().all(|point| {
                point.y <= room.depth1 + 1.0e-12 || point.x <= room.width2 + 1.0e-12
            })
        );
        assert!(mesh.nodes.iter().any(|point| {
            (point.x - room.width2).abs() < 1.0e-12 && (point.y - room.depth1).abs() < 1.0e-12
        }));
    }
}
